diff -ruN --exclude=node_modules --exclude=.git a/csv.test.ts b/csv.test.ts
--- a/csv.test.ts	2026-10-24 00:04:57
+++ b/csv.test.ts	2026-10-24 00:06:31
@@ -23,3 +23,150 @@
   expect(s.push("d")).toEqual([]);
   expect(s.end()).toEqual([["c", "d"]]);
 });
+
+function mulberry32(seed: number) {
+  return () => {
+    seed = (seed + 0x6d2b79f5) | 0;
+    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
+    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
+    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
+  };
+}
+
+function runStream(chunks: string[]): string[][] {
+  const s = new CsvStream();
+  const rows: string[][] = [];
+  for (const c of chunks) rows.push(...s.push(c));
+  rows.push(...s.end());
+  return rows;
+}
+
+function splitAt(text: string, cuts: number[]): string[] {
+  const chunks: string[] = [];
+  let prev = 0;
+  for (const cut of [...cuts, text.length]) {
+    chunks.push(text.slice(prev, cut));
+    prev = cut;
+  }
+  return chunks;
+}
+
+test("every split of a random input gives the same rows as parseCsv", () => {
+  const rand = mulberry32(42);
+  const alphabet = ['a', ",", '"', "\r", "\n", "\uFEFF"];
+  for (let k = 0; k < 5000; k++) {
+    const len = Math.floor(rand() * 13);
+    let text = "";
+    for (let j = 0; j < len; j++) text += alphabet[Math.floor(rand() * alphabet.length)];
+    const cuts: number[] = [];
+    const nCuts = Math.floor(rand() * (len + 3));
+    for (let j = 0; j < nCuts; j++) cuts.push(Math.floor(rand() * (len + 1)));
+    cuts.sort((x, y) => x - y);
+    const chunks = splitAt(text, cuts);
+    let expected: string[][] | undefined;
+    try {
+      expected = parseCsv(text);
+    } catch (e) {
+      expect(e).toBeInstanceOf(SyntaxError);
+    }
+    if (expected === undefined) {
+      expect(() => runStream(chunks), JSON.stringify({ text, chunks })).toThrow(SyntaxError);
+    } else {
+      expect(runStream(chunks), JSON.stringify({ text, chunks })).toEqual(expected);
+    }
+  }
+});
+
+test("every two-chunk split of the edge cases matches parseCsv", () => {
+  const cases = ['"x"', 'a"', "a\r", "a\r\r\n", '"a"\r', '"a', "\uFEFFa", "a\uFEFF", "a\n", "\n", "a,", '"a""b"\r\n', "\r\"", ""];
+  for (const text of cases) {
+    for (let cut = 0; cut <= text.length; cut++) {
+      const chunks = [text.slice(0, cut), text.slice(cut)];
+      let expected: string[][] | undefined;
+      try {
+        expected = parseCsv(text);
+      } catch {
+        expected = undefined;
+      }
+      if (expected === undefined) expect(() => runStream(chunks)).toThrow(SyntaxError);
+      else expect(runStream(chunks)).toEqual(expected);
+    }
+  }
+});
+
+test("a quote split across chunks is kept as one quote", () => {
+  expect(runStream(['"x"', '"y"'])).toEqual([['x"y']]);
+});
+
+test("a quoted field can continue across chunks", () => {
+  expect(runStream(['"x"', ",y\n"])).toEqual([["x", "y"]]);
+});
+
+test("a carriage return at the end of a chunk waits for the next chunk", () => {
+  const s = new CsvStream();
+  expect(s.push("a\r")).toEqual([]);
+  expect(s.push("\nb")).toEqual([["a"]]);
+  expect(s.end()).toEqual([["b"]]);
+});
+
+test("a carriage return at the end of the input stays in the field", () => {
+  const s = new CsvStream();
+  expect(s.push("a\r")).toEqual([]);
+  expect(s.end()).toEqual([["a\r"]]);
+});
+
+test("a closing quote and a carriage return at the end of the input is a SyntaxError", () => {
+  const s = new CsvStream();
+  expect(s.push('"a"\r')).toEqual([]);
+  expect(() => s.end()).toThrow(SyntaxError);
+});
+
+test("an open quoted field at the end of the input is a SyntaxError", () => {
+  const s = new CsvStream();
+  expect(s.push('"a')).toEqual([]);
+  expect(() => s.end()).toThrow(SyntaxError);
+});
+
+test("a BOM after an empty chunk is still dropped", () => {
+  expect(runStream(["", "\uFEFFa"])).toEqual([["a"]]);
+});
+
+test("a BOM later in the input is kept", () => {
+  expect(runStream(["a", "\uFEFF"])).toEqual([["a\uFEFF"]]);
+});
+
+test("a row end just before the end gives no extra row", () => {
+  expect(runStream(["a\n"])).toEqual([["a"]]);
+});
+
+test("a single line feed is one row with one empty field", () => {
+  expect(runStream(["\n"])).toEqual([[""]]);
+});
+
+test("a trailing comma gives an empty last field", () => {
+  expect(runStream(["a,"])).toEqual([["a", ""]]);
+});
+
+test("a quote after a carriage return in an unquoted field is a SyntaxError", () => {
+  const s = new CsvStream();
+  expect(s.push("a\r")).toEqual([]);
+  expect(() => s.push('"')).toThrow(SyntaxError);
+});
+
+test("a long stream of one-character chunks is fast and correct", () => {
+  const quoted = '"' + "x,\r\n".repeat(250_000) + '"';
+  const s = new CsvStream();
+  let rows: string[][] = [];
+  for (const c of quoted) rows.push(...s.push(c));
+  rows.push(...s.end());
+  expect(rows).toEqual([["x,\r\n".repeat(250_000)]]);
+
+  const short = "ab,cd\n".repeat(200_000);
+  const t = new CsvStream();
+  rows = [];
+  for (const c of short) rows.push(...t.push(c));
+  rows.push(...t.end());
+  expect(rows.length).toBe(200_000);
+  expect(rows[0]).toEqual(["ab", "cd"]);
+  expect(rows[199_999]).toEqual(["ab", "cd"]);
+}, 4000);
diff -ruN --exclude=node_modules --exclude=.git a/csv.ts b/csv.ts
--- a/csv.ts	2026-10-24 00:04:57
+++ b/csv.ts	2026-10-24 00:06:19
@@ -50,3 +50,138 @@
   rows.push(row);
   return rows;
 }
+
+type StreamState = "start" | "unquoted" | "cr" | "quoted" | "quoteInQuoted" | "afterClose" | "crAfterClose";
+
+const unquotedSpecial = /[,\r\n"]/g;
+
+/**
+ * Reads CSV in chunks of any size and gives the same rows as `parseCsv` does on all the chunks joined together.
+ * Each character is handled once, so the work for a chunk depends only on its own length.
+ */
+export class CsvStream {
+  private state: StreamState = "start";
+  private field = "";
+  private row: string[] = [];
+  private bomChecked = false;
+
+  push(chunk: string): string[][] {
+    const rows: string[][] = [];
+    const n = chunk.length;
+    let i = 0;
+    if (!this.bomChecked && n > 0) {
+      this.bomChecked = true;
+      if (chunk[0] === "﻿") i = 1;
+    }
+    while (i < n) {
+      const c = chunk[i]!;
+      switch (this.state) {
+        case "start":
+          i++;
+          if (c === '"') this.state = "quoted";
+          else if (c === ",") this.row.push("");
+          else if (c === "\n") this.emit(rows);
+          else if (c === "\r") this.state = "cr";
+          else {
+            this.field = c;
+            this.state = "unquoted";
+          }
+          break;
+        case "unquoted": {
+          unquotedSpecial.lastIndex = i;
+          const m = unquotedSpecial.exec(chunk);
+          const end = m ? m.index : n;
+          this.field += chunk.slice(i, end);
+          i = end;
+          if (i >= n) break;
+          const d = chunk[i++];
+          if (d === '"') throw new SyntaxError(`a quote in a field that is not quoted, at offset ${i - 1}`);
+          if (d === ",") {
+            this.row.push(this.field);
+            this.field = "";
+            this.state = "start";
+          } else if (d === "\n") this.emit(rows);
+          else this.state = "cr";
+          break;
+        }
+        case "cr":
+          if (c === "\n") {
+            i++;
+            this.emit(rows);
+          } else {
+            if (c === "\r") i++;
+            this.field += "\r";
+            this.state = c === "\r" ? "cr" : "unquoted";
+          }
+          break;
+        case "quoted": {
+          const q = chunk.indexOf('"', i);
+          if (q < 0) {
+            this.field += chunk.slice(i);
+            i = n;
+          } else {
+            this.field += chunk.slice(i, q);
+            this.state = "quoteInQuoted";
+            i = q + 1;
+          }
+          break;
+        }
+        case "quoteInQuoted":
+          if (c === '"') {
+            this.field += '"';
+            this.state = "quoted";
+            i++;
+          } else this.state = "afterClose";
+          break;
+        case "afterClose":
+          if (c === ",") {
+            this.row.push(this.field);
+            this.field = "";
+            this.state = "start";
+          } else if (c === "\n") this.emit(rows);
+          else if (c === "\r") this.state = "crAfterClose";
+          else throw new SyntaxError(`unexpected ${JSON.stringify(c)} after a closing quote`);
+          i++;
+          break;
+        case "crAfterClose":
+          if (c !== "\n") throw new SyntaxError(`unexpected ${JSON.stringify(c)} after a closing quote`);
+          i++;
+          this.emit(rows);
+          break;
+      }
+    }
+    return rows;
+  }
+
+  end(): string[][] {
+    switch (this.state) {
+      case "start":
+        if (this.row.length === 0) return [];
+        this.row.push("");
+        break;
+      case "unquoted":
+      case "quoteInQuoted":
+      case "afterClose":
+        this.row.push(this.field);
+        break;
+      case "cr":
+        this.row.push(this.field + "\r");
+        break;
+      case "quoted":
+        throw new SyntaxError("a quoted field is still open at the end of the input");
+      case "crAfterClose":
+        throw new SyntaxError("a carriage return after a closing quote at the end of the input");
+    }
+    const row = this.row;
+    this.row = [];
+    return [row];
+  }
+
+  private emit(rows: string[][]) {
+    this.row.push(this.field);
+    rows.push(this.row);
+    this.row = [];
+    this.field = "";
+    this.state = "start";
+  }
+}

