 //   (none means `.`). Any start path that cannot be resolved or is outside cwd: rm-outside. cwd itself is fine.
 //
 // Anything else: undefined.
+const unresolvable = (p: string) => p.includes('$') || (p.startsWith('~') && p !== '~' && !p.startsWith('~/'));
+
+const shortGroup = (w: string) => w.startsWith('-') && !w.startsWith('--') && w.length > 1;
+
+const hit = (name: Hit['name'], reason: string): Hit => ({ name, reason });
+
+const gitValueOptions = ['-C', '-c', '--git-dir', '--work-tree', '--namespace'];
+const pushForceFlags = ['--force', '--force-with-lease', '--mirror', '--delete', '--prune'];
+
+function gitDenied(argv: string[]): Hit | undefined {
+  let i = 1;
+  while (i < argv.length && argv[i].startsWith('-')) i += gitValueOptions.includes(argv[i]) ? 2 : 1;
+  const sub = argv[i];
+  if (sub === undefined) return undefined;
+  const rest = argv.slice(i + 1);
+
+  if (sub === 'push') {
+    const forced = rest.some(
+      (w) =>
+        pushForceFlags.some((f) => w === f || w.startsWith(f + '=')) ||
+        (shortGroup(w) && /[fd]/.test(w)) ||
+        (!w.startsWith('-') && (w.startsWith('+') || w.startsWith(':'))),
+    );
+    return forced ? hit('force-push', 'git push --force rewrites remote history') : undefined;
+  }
+  if (sub === 'reset' && rest.includes('--hard')) return hit('reset-hard', 'git reset --hard discards uncommitted work');
+  if (sub === 'clean') {
+    const force = rest.some((w) => w === '--force' || (shortGroup(w) && w.includes('f')));
+    const dry = rest.some((w) => w === '-n' || w === '--dry-run');
+    if (force && !dry) return hit('clean-force', 'git clean -f deletes untracked files');
+  }
+  return undefined;
+}
+
+function rmDenied(argv: string[], cwd: string): Hit | undefined {
+  let recursive = false;
+  const targets: string[] = [];
+  let endOfFlags = false;
+  for (const w of argv.slice(1)) {
+    if (endOfFlags) targets.push(w);
+    else if (w === '--') endOfFlags = true;
+    else if (w === '--recursive') recursive = true;
+    else if (shortGroup(w)) recursive ||= /[rR]/.test(w);
+    else if (!w.startsWith('-')) targets.push(w);
+  }
+  if (!recursive) return undefined;
+  const outside = 'recursive rm outside the working directory';
+  if (targets.length === 0) return hit('rm-outside', outside);
+  for (const t of targets)
+    if (unresolvable(t) || !insideWorkspace(t, cwd) || sameDir(t, cwd)) return hit('rm-outside', outside);
+  return undefined;
+}
+
+function findDenied(argv: string[], cwd: string): Hit | undefined {
+  const args = argv.slice(1);
+  if (!args.some((w) => w === '-delete' || w === '-exec' || w === '-execdir')) return undefined;
+  const firstFlag = args.findIndex((w) => w.startsWith('-'));
+  const starts = firstFlag === -1 ? args : args.slice(0, firstFlag);
+  if (starts.length === 0) starts.push('.');
+  for (const p of starts)
+    if (unresolvable(p) || !insideWorkspace(p, cwd))
+      return hit('rm-outside', 'find -delete or -exec outside the working directory');
+  return undefined;
+}
+
 export function denyListed(argv: string[], cwd: string): Hit | undefined {
-  throw new Error('not implemented');
+  if (argv.length === 0) return undefined;
+  const cmd = argv[0].split('/').pop();
+  if (cmd === 'git') return gitDenied(argv);
+  if (cmd === 'rm') return rmDenied(argv, cwd);
+  if (cmd === 'find') return findDenied(argv, cwd);
+  return undefined;
 }

