@@ -23,5 +23,92 @@
 // - nothing matched: message contains "not found", and when the first non-blank line of old_text (trimmed) occurs
 //   in some lines of content, "first line appears at line L1, L2" (at most 5 lines).
 export function applyEdit(content: string, edit: TextEdit): { content: string; applied: Applied } | { error: string } {
-  throw new Error('not implemented');
+  const { old_text: old, new_text: nw, replace_all } = edit;
+  if (old === '') return { error: 'old_text is empty; use write to create or overwrite a file' };
+  if (old === nw) return { error: 'old_text and new_text are the same; nothing to change' };
+
+  // Tier 1: exact, with non-overlapping matches.
+  const lineAt = (idx: number) => content.slice(0, idx).split('\n').length;
+  const hits: number[] = [];
+  for (let i = content.indexOf(old); i !== -1; i = content.indexOf(old, i + old.length)) hits.push(i);
+  if (hits.length === 1) {
+    const i = hits[0];
+    return {
+      content: content.slice(0, i) + nw + content.slice(i + old.length),
+      applied: { from: lineAt(i), to: lineAt(i + old.length - 1), tier: 'exact', count: 1 },
+    };
+  }
+  if (hits.length > 1) {
+    if (!replace_all) {
+      return { error: `old_text matches ${hits.length} places (first at line ${lineAt(hits[0])}); add context or set replace_all` };
+    }
+    return {
+      content: content.split(old).join(nw),
+      applied: { from: lineAt(hits[0]), to: lineAt(hits[hits.length - 1] + old.length - 1), tier: 'exact', count: hits.length },
+    };
+  }
+
+  // Tiers 2 and 3: whole-line windows.
+  const strip = (s: string) => (s.endsWith('\n') ? s.slice(0, -1) : s);
+  const oldLines = strip(old).split('\n');
+  const newStripped = strip(nw);
+  const newLines = newStripped === '' ? [] : newStripped.split('\n');
+  // The text after a final newline is not a line, so it is left out of the matchable lines.
+  const hasFinalNl = content.endsWith('\n');
+  const lines = (hasFinalNl ? content.slice(0, -1) : content).split('\n');
+  const findWindows = (norm: (s: string) => string) => {
+    const starts: number[] = [];
+    for (let i = 0; i + oldLines.length <= lines.length; i++) {
+      if (oldLines.every((l, k) => norm(lines[i + k]) === norm(l))) starts.push(i);
+    }
+    return starts;
+  };
+  const indentOf = (s: string) => s.match(/^\s*/)![0];
+  const firstNonBlank = (ls: string[]) => ls.find((l) => l.trim() !== '') ?? '';
+
+  const tiers: { norm: (s: string) => string; tier: Tier; label: string; reindent: boolean }[] = [
+    { norm: (s) => s.trimEnd(), tier: 'trailing-space', label: '(ignoring trailing whitespace)', reindent: false },
+    { norm: (s) => s.trim(), tier: 'indentation', label: '(ignoring indentation)', reindent: true },
+  ];
+  for (const t of tiers) {
+    const starts = findWindows(t.norm);
+    if (starts.length === 0) continue;
+    if (starts.length > 1) {
+      return { error: `old_text matches ${starts.length} places ${t.label} at lines ${starts.map((i) => i + 1).join(', ')}` };
+    }
+    const i = starts[0];
+    let repl = newLines;
+    if (t.reindent) {
+      const oldIndent = indentOf(firstNonBlank(oldLines));
+      const fileIndent = indentOf(firstNonBlank(lines.slice(i, i + oldLines.length)));
+      repl = newLines.map((l) => {
+        if (l.trim() === '') return '';
+        if (l.startsWith(oldIndent)) return fileIndent + l.slice(oldIndent.length);
+        // Less indented than old_text's anchor: move it by the same amount, not below column 0.
+        const ind = indentOf(l);
+        if (oldIndent.startsWith(ind)) {
+          const shift = oldIndent.length - ind.length;
+          return fileIndent.slice(0, Math.max(0, fileIndent.length - shift)) + l.slice(ind.length);
+        }
+        return l;
+      });
+    }
+    const out = [...lines.slice(0, i), ...repl, ...lines.slice(i + oldLines.length)].join('\n');
+    return {
+      content: hasFinalNl ? out + '\n' : out,
+      applied: { from: i + 1, to: i + oldLines.length, tier: t.tier, count: 1 },
+    };
+  }
+
+  // Nothing matched: point at where the first line of old_text appears.
+  let msg = 'old_text not found';
+  const first = firstNonBlank(oldLines).trim();
+  if (first) {
+    const hitLines: number[] = [];
+    lines.forEach((l, idx) => {
+      if (hitLines.length < 5 && l.includes(first)) hitLines.push(idx + 1);
+    });
+    if (hitLines.length) msg += `; first line appears at line ${hitLines.join(', ')}`;
+  }
+  return { error: msg };
 }

