diff -ruN --exclude=node_modules --exclude=.git a/src/core/tools/spawn.ts b/src/core/tools/spawn.ts
--- a/src/core/tools/spawn.ts	1970-01-01 07:00:00
+++ b/src/core/tools/spawn.ts	2026-10-24 00:30:50
@@ -0,0 +1,48 @@
+import type { Evidence, ToolOutput } from '../types.ts';
+import { clip, type ToolSpec } from './registry.ts';
+
+// A sub-thread: a session of its own, started by a writer with a task. Only its report comes back to the writer.
+export type SpawnKind = 'explore' | 'work';
+const KINDS: SpawnKind[] = ['explore', 'work'];
+
+export function spawnTool(start: (kind: SpawnKind, task: string, signal: AbortSignal) => Promise<ToolOutput>): ToolSpec {
+  return {
+    name: 'spawn',
+    description:
+      'Hand a task to a sub-thread: a fresh session with its own context. kind "explore" is read-only, cheap and fast, and several can run in parallel. kind "work" may edit files and runs alone, with the same checks as you. The task must be a full brief: the sub-thread has none of your context, so give the goal, the paths and facts it needs, and what to report back. Only its final report comes back to you.',
+    schema: {
+      type: 'object',
+      properties: {
+        kind: { type: 'string', enum: KINDS, description: 'explore (read-only) or work (may edit)' },
+        task: { type: 'string', description: 'The full brief for the sub-thread' },
+      },
+      required: ['kind', 'task'],
+      additionalProperties: false,
+    },
+    effect: 'write_workspace',
+    effectOf: (input) => (input.kind === 'explore' ? 'read' : 'write_workspace'),
+    replay: 'unsafe',
+    async run(input, ctx) {
+      const kind = String(input.kind ?? '');
+      const task = String(input.task ?? '').trim();
+      if (!KINDS.includes(kind as SpawnKind)) return { text: 'kind must be explore or work', isError: true };
+      if (!task) return { text: 'task is required', isError: true };
+      return start(kind as SpawnKind, task, ctx.signal);
+    },
+  };
+}
+
+// Added to the sub-thread's preamble: what it is and what its reply is for.
+export const subThreadNote = (kind: SpawnKind) =>
+  `You are a sub-thread: a session started by another session with the task above. You have none of its context. Your final reply is the only thing it sees, so say what you found or changed, with paths, and what is left.${kind === 'explore' ? ' You are read-only: look, do not change anything.' : ''}`;
+
+export function subThreadReport({ id, kind, model, subtype, result, evidence }: { id?: string; kind: SpawnKind; model: string; subtype: string; result: string; evidence?: Evidence }): string {
+  const lines = [`<sub-thread${id ? ` id="${id}"` : ''} kind="${kind}" model="${model}" ended="${subtype}">`, result.trim() || '(no report)'];
+  if (kind === 'work') {
+    lines.push(`Changed: ${evidence?.changed.length ? evidence.changed.join(', ') : 'none'}`);
+    if (evidence?.checks.length) lines.push(`Checks: ${evidence.checks.map((c) => `${c.command} (exit ${c.exitCode})`).join(', ')}`);
+    lines.push('cedia counts these changes as yours: run a declared check before you report done.');
+  }
+  lines.push('</sub-thread>');
+  return clip(lines.join('\n'));
+}
