diff -ruN --exclude=node_modules --exclude=.git a/src/core/project/handoff.ts b/src/core/project/handoff.ts
--- a/src/core/project/handoff.ts	1970-01-01 07:00:00
+++ b/src/core/project/handoff.ts	2026-10-24 00:36:30
@@ -0,0 +1,39 @@
+import type { EventOf, ModelSpec, SessionEvent } from '../types.ts';
+
+// The prompt a session gets once its context is long: it writes a note and ends, and a new session of the thread goes on.
+export const HANDOFF_PROMPT = `Your context is long, so this session ends here. A new session of the same thread goes on from the task and your note only; it can search this session's log with the recall tool. Write the note now as plain text with no tool calls. Cover: what is done (files changed, checks run and their results), what is left, the next step, and anything you learned that the code does not show.`;
+
+export const HANDOFF_NO_TOOLS = 'not run: write the handoff note now, as text with no tool calls; the next session can run this.';
+
+// Half the window, at most 150k tokens, and below the long-context price tier so a run does not pay the higher rate.
+export function defaultHandoffAt(model: ModelSpec): number {
+  const above = model.price.above;
+  return Math.min(Math.floor(model.caps.contextWindow / 2), 150_000, above ? Math.floor(above.tokens * 0.9) : Infinity);
+}
+
+// The last usage plus chars/4 for everything logged after it (see SPEC.md).
+export function contextTokens(events: SessionEvent[]): number | undefined {
+  const at = events.findLastIndex((e) => e.kind === 'assistant' && e.stop !== 'aborted');
+  if (at < 0) return undefined;
+  const a = events[at] as EventOf<'assistant'>;
+  let tokens = a.usage.uncached + a.usage.cacheRead + a.usage.cacheWrite + a.usage.output;
+  let chars = 0;
+  for (const e of events.slice(at + 1)) {
+    if (e.kind === 'tool_result') chars += e.output.text.length;
+    else if (e.kind === 'user' || e.kind === 'reminder') chars += e.text.length;
+  }
+  return tokens + Math.ceil(chars / 4);
+}
+
+// The input the first assistant reply saw: how big the session started.
+export function firstContext(events: SessionEvent[]): number | undefined {
+  const a = events.find((e): e is EventOf<'assistant'> => e.kind === 'assistant');
+  return a ? a.usage.uncached + a.usage.cacheRead + a.usage.cacheWrite : undefined;
+}
+
+export function shouldHandOff(events: SessionEvent[], at: number): boolean {
+  const now = contextTokens(events);
+  const first = firstContext(events);
+  if (now === undefined || first === undefined) return false;
+  return now > at && now >= 2 * first;
+}
diff -ruN --exclude=node_modules --exclude=.git a/src/core/project/threads.ts b/src/core/project/threads.ts
--- a/src/core/project/threads.ts	1970-01-01 07:00:00
+++ b/src/core/project/threads.ts	2026-10-24 00:42:24
@@ -0,0 +1,165 @@
+import { appendFileSync, existsSync, mkdirSync, readdirSync, readFileSync } from 'node:fs';
+import { join } from 'node:path';
+
+// A thread is one task that one or more sessions work on. Its log is an append-only JSONL file per thread.
+export type ThreadState = 'working' | 'done' | 'stopped';
+
+export type ThreadEventBody =
+  | { kind: 'thread'; task: string }
+  | { kind: 'session'; sessionId: string; model: string; role: string; why: 'start' | 'handoff' | 'resume' | 'fallback' }
+  | { kind: 'handoff'; sessionId: string; note: string }
+  | { kind: 'message'; id: string; from: string; text: string }
+  | { kind: 'delivered'; ids: string[]; sessionId: string }
+  | { kind: 'state'; state: ThreadState; result?: string; sessionId?: string };
+
+export type ThreadEvent = ThreadEventBody & { at: string };
+export type ThreadMessage = { id: string; from: string; text: string; at: string };
+
+export type Thread = {
+  id: string;
+  title: string;
+  task: string;
+  state: ThreadState;
+  result?: string;
+  handoff?: { sessionId: string; note: string };
+  latest?: { kind: 'handoff' | 'result'; sessionId?: string; text: string };
+  sessions: { sessionId: string; model: string; role: string; why: 'start' | 'handoff' | 'resume' | 'fallback'; at: string }[];
+  messages: ThreadMessage[];
+  pending: ThreadMessage[];
+  updated: string;
+};
+
+const THREAD_ID = /^t-[0-9a-f]{8}$/;
+const MESSAGE_ID = () => `m-${crypto.randomUUID().slice(0, 8)}`;
+
+export const threadsDir = (home: string, slug: string) => join(home, 'projects', slug, 'threads');
+
+export function titleOf(task: string): string {
+  const line = task.trim().split('\n')[0]!.trim();
+  return line.length > 60 ? `${line.slice(0, 57)}...` : line;
+}
+
+export function foldThread(id: string, events: ThreadEvent[]): Thread {
+  const t: Thread = { id, title: '', task: '', state: 'working', sessions: [], messages: [], pending: [], updated: '' };
+  const delivered = new Set<string>();
+  for (const e of events) {
+    t.updated = e.at;
+    switch (e.kind) {
+      case 'thread':
+        t.task = e.task;
+        t.title = titleOf(e.task);
+        break;
+      case 'session':
+        t.sessions.push({ sessionId: e.sessionId, model: e.model, role: e.role, why: e.why, at: e.at });
+        break;
+      case 'handoff':
+        t.handoff = { sessionId: e.sessionId, note: e.note };
+        t.latest = { kind: 'handoff', sessionId: e.sessionId, text: e.note };
+        break;
+      case 'message':
+        t.messages.push({ id: e.id, from: e.from, text: e.text, at: e.at });
+        break;
+      case 'delivered':
+        for (const id of e.ids) delivered.add(id);
+        break;
+      case 'state':
+        t.state = e.state;
+        if (e.result !== undefined) {
+          t.result = e.result;
+          t.latest = { kind: 'result', sessionId: e.sessionId ?? t.sessions.at(-1)?.sessionId, text: e.result };
+        }
+        break;
+    }
+  }
+  t.pending = t.messages.filter((m) => !delivered.has(m.id));
+  return t;
+}
+
+export class ThreadStore {
+  constructor(private dir: string) {}
+
+  private file(id: string): string {
+    return join(this.dir, `${id}.jsonl`);
+  }
+
+  has(id: string): boolean {
+    return THREAD_ID.test(id) && existsSync(this.file(id));
+  }
+
+  private check(id: string): void {
+    if (!THREAD_ID.test(id)) throw new Error(`${id} is not a thread id`);
+    if (!this.has(id)) throw new Error(`no thread ${id} in this project`);
+  }
+
+  private write(id: string, body: ThreadEventBody): void {
+    appendFileSync(this.file(id), `${JSON.stringify({ ...body, at: new Date().toISOString() })}\n`);
+  }
+
+  private events(id: string): ThreadEvent[] {
+    return readFileSync(this.file(id), 'utf8')
+      .split('\n')
+      .filter((l) => l.trim())
+      .map((l) => JSON.parse(l) as ThreadEvent);
+  }
+
+  open(task: string): string {
+    mkdirSync(this.dir, { recursive: true });
+    const id = `t-${crypto.randomUUID().slice(0, 8)}`;
+    this.write(id, { kind: 'thread', task });
+    return id;
+  }
+
+  append(id: string, body: ThreadEventBody): void {
+    this.check(id);
+    this.write(id, body);
+  }
+
+  send(id: string, from: string, text: string): string {
+    const mid = MESSAGE_ID();
+    this.append(id, { kind: 'message', id: mid, from, text });
+    return mid;
+  }
+
+  read(id: string): Thread {
+    this.check(id);
+    return foldThread(id, this.events(id));
+  }
+
+  list(): Thread[] {
+    if (!existsSync(this.dir)) return [];
+    return readdirSync(this.dir)
+      .filter((f) => f.endsWith('.jsonl'))
+      .map((f) => foldThread(f.slice(0, -'.jsonl'.length), this.events(f.slice(0, -'.jsonl'.length))))
+      .sort((a, b) => (a.updated < b.updated ? 1 : a.updated > b.updated ? -1 : 0));
+  }
+
+  inbox(threadId: string, sessionId: string) {
+    return {
+      pending: (): { ids: string[]; text: string } | undefined => {
+        const pending = this.read(threadId).pending;
+        if (pending.length === 0) return undefined;
+        // A message cannot close or open a block of its own: its "<message" and "</message" are escaped.
+        const body = pending.map((m) => `<message from="${m.from}" at="${m.at}">\n${m.text.replace(/<(\/?message)/g, '&lt;$1')}\n</message>`).join('\n');
+        return {
+          ids: pending.map((m) => m.id),
+          text: `Messages sent to this thread (from="user" is the user; other senders are other threads of this project):\n${body}`,
+        };
+      },
+      delivered: (ids: string[]) => this.append(threadId, { kind: 'delivered', ids, sessionId }),
+    };
+  }
+}
+
+export function threadBrief(t: Thread): string {
+  const parts = [`thread ${t.id} (${t.state}, ${t.sessions.length} sessions)`, `<task>\n${t.task}\n</task>`];
+  if (t.latest) {
+    const kind = t.latest.kind;
+    const open = t.latest.sessionId ? `${kind} session="${t.latest.sessionId}"` : kind;
+    parts.push(`<${open}>\n${t.latest.text}\n</${kind}>`);
+  }
+  return parts.join('\n\n');
+}
+
+export function threadContext(t: Thread): string {
+  return `This is thread ${t.id}. Earlier sessions of it worked on this task; the recall tool searches their logs. Go on from where the latest one stopped.\n\n${threadBrief(t)}`;
+}
diff -ruN --exclude=node_modules --exclude=.git a/src/core/tools/threads.ts b/src/core/tools/threads.ts
--- a/src/core/tools/threads.ts	1970-01-01 07:00:00
+++ b/src/core/tools/threads.ts	2026-10-24 00:35:44
@@ -0,0 +1,137 @@
+import type { EventOf, SessionEvent } from '../types.ts';
+import { threadBrief, type ThreadStore } from '../project/threads.ts';
+import { clip, type ToolSpec } from './registry.ts';
+
+const MAX_MATCHES = 40;
+const MAX_LINE = 300;
+
+// Searches the logs of the earlier sessions of a thread. Each source is one session.
+export function recallTool(sources: () => { id: string; events: () => SessionEvent[] }[]): ToolSpec {
+  return {
+    name: 'recall',
+    description: 'Search the logs of the earlier sessions of this thread: user and assistant text, tool calls and tool results. The query is a regex or plain text.',
+    schema: {
+      type: 'object',
+      properties: { query: { type: 'string', description: 'A regex or plain text to search for' } },
+      required: ['query'],
+      additionalProperties: false,
+    },
+    effect: 'read',
+    replay: 'safe',
+    async run(input) {
+      const query = String(input.query ?? '');
+      if (!query) return { text: 'query is required', isError: true };
+      let re: RegExp;
+      try {
+        re = new RegExp(query, 'i');
+      } catch {
+        re = new RegExp(query.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'i');
+      }
+      const all = sources();
+      const hits: string[] = [];
+      all.forEach((src, i) => {
+        const names = new Map<string, string>();
+        const search = (label: string, text: string) => {
+          for (const line of text.split('\n')) {
+            const m = re.exec(line);
+            if (!m) continue;
+            hits.push(`[session ${i + 1} of ${all.length} · ${label}] ${window(line, m.index)}`);
+          }
+        };
+        for (const e of src.events()) {
+          if (e.kind === 'user' || e.kind === 'reminder') search(e.kind, e.text);
+          else if (e.kind === 'assistant') {
+            for (const b of e.blocks) {
+              if (b.type === 'text') search('assistant', b.text);
+              else if (b.type === 'tool_use') {
+                names.set(b.id, b.name);
+                search(`call ${b.name}`, JSON.stringify(b.input));
+              }
+            }
+          } else if (e.kind === 'tool_result') {
+            search(`result ${names.get(e.callId) ?? 'tool'}`, e.output.text);
+          }
+        }
+      });
+      if (hits.length === 0) return { text: `no match for ${query} in ${all.length} earlier sessions`, isError: false };
+      const n = hits.length;
+      const shown = hits.slice(0, MAX_MATCHES);
+      if (n > MAX_MATCHES) shown.push(`[${n - MAX_MATCHES} more matches left out; use a narrower query]`);
+      return { text: clip([`${n} match${n === 1 ? '' : 'es'}`, ...shown].join('\n')), isError: false };
+    },
+  };
+}
+
+// The part of a long line around the match, with the cuts marked.
+function window(line: string, at: number): string {
+  if (line.length <= MAX_LINE) return line;
+  const start = Math.max(0, Math.min(at - MAX_LINE / 2, line.length - MAX_LINE));
+  const end = start + MAX_LINE;
+  return `${start > 0 ? '...' : ''}${line.slice(start, end)}${end < line.length ? '...' : ''}`;
+}
+
+export function threadTools(store: ThreadStore, me: string): ToolSpec[] {
+  const threads: ToolSpec = {
+    name: 'threads',
+    description: 'List the other threads of this project with their state and latest note or result.',
+    schema: { type: 'object', properties: {}, required: [], additionalProperties: false },
+    effect: 'read',
+    replay: 'safe',
+    async run() {
+      const others = store.list().filter((t) => t.id !== me);
+      if (others.length === 0) return { text: 'no other threads in this project', isError: false };
+      const lines = others.flatMap((t) => {
+        const head = `${t.id} [${t.state}] ${t.title}`;
+        return t.latest ? [head, `  ${t.latest.kind === 'handoff' ? 'note' : 'result'}: ${clip(t.latest.text, 300)}`] : [head];
+      });
+      return { text: lines.join('\n'), isError: false };
+    },
+  };
+
+  const read_thread: ToolSpec = {
+    name: 'read_thread',
+    description: 'Read the task, state and latest note or result of another thread of this project.',
+    schema: {
+      type: 'object',
+      properties: { id: { type: 'string', description: 'Thread id, e.g. t-1a2b3c4d' } },
+      required: ['id'],
+      additionalProperties: false,
+    },
+    effect: 'read',
+    replay: 'safe',
+    async run(input) {
+      try {
+        return { text: threadBrief(store.read(String(input.id ?? ''))), isError: false };
+      } catch (e) {
+        return { text: (e as Error).message, isError: true };
+      }
+    },
+  };
+
+  const message_thread: ToolSpec = {
+    name: 'message_thread',
+    description: 'Send a message to another thread of this project. The thread reads it when its next session starts or resumes.',
+    schema: {
+      type: 'object',
+      properties: {
+        id: { type: 'string', description: 'Thread id, e.g. t-1a2b3c4d' },
+        text: { type: 'string', description: 'The message' },
+      },
+      required: ['id', 'text'],
+      additionalProperties: false,
+    },
+    effect: 'write_workspace',
+    replay: 'unsafe',
+    async run(input) {
+      const id = String(input.id ?? '');
+      const text = String(input.text ?? '');
+      if (id === me) return { text: 'this is your own thread', isError: true };
+      if (!store.has(id)) return { text: `no thread ${id} in this project`, isError: true };
+      if (!text) return { text: 'text is required', isError: true };
+      store.send(id, me, text);
+      return { text: `sent to ${id}`, isError: false };
+    },
+  };
+
+  return [threads, read_thread, message_thread];
+}
