+import { describe, expect, test } from 'bun:test';
+import { cart } from '../src/cart/cart.ts';
+import { totals } from '../src/order/total.ts';
+
+// Expected values worked by hand from the rules in README.md.
+describe('pricing rules', () => {
+  test('exactly 10 units gets 5% bulk discount', () => {
+    // 10 pens = 1200; 5% = 60; subtotal 1140 < 5000 so shipping 800; tax 7% of 1940 = 135.8 -> 136
+    const t = totals(cart('US', [['PEN', 10]]));
+    expect(t).toMatchObject({ subtotal: 1140, shipping: 800, tax: 136, total: 2076 });
+    expect(t.lines[0].discount).toBe(60);
+  });
+
+  test('exactly 50 units gets 10% bulk discount', () => {
+    // 50 pens = 6000; 10% = 600; subtotal 5400 >= 5000 so free shipping; tax 7% of 5400 = 378
+    expect(totals(cart('US', [['PEN', 50]]))).toMatchObject({ subtotal: 5400, shipping: 0, tax: 378, total: 5778 });
+  });
+
+  test('same sku on separate lines is merged before pricing', () => {
+    // 6 + 4 pens = 10 pens, so the 5% tier applies to the merged line
+    const t = totals(cart('US', [['PEN', 6], ['PEN', 4]]));
+    expect(t.lines.length).toBe(1);
+    expect(t.lines[0].quantity).toBe(10);
+    expect(t).toMatchObject({ subtotal: 1140, total: 2076 });
+  });
+
+  test('coupon can push an order below free shipping', () => {
+    // 3 bags = 6600; SAVE10 = 660; discounted 5940 < 6000 so shipping 900; tax 20% of 6840 = 1368
+    expect(totals(cart('EU', [['BAG', 3]], 'SAVE10'))).toMatchObject({ subtotal: 6600, coupon: 660, shipping: 900, tax: 1368, total: 8208 });
+  });
+
+  test('UK free shipping threshold is 4000', () => {
+    // 2 bags = 4400 >= 4000 so free shipping; tax 20% of 4400 = 880
+    expect(totals(cart('UK', [['BAG', 2]]))).toMatchObject({ subtotal: 4400, shipping: 0, tax: 880, total: 5280 });
+  });
+});

