+
+test('parseDuration parses valid input', () => {
+  expect(parseDuration('1.5h')).toBe(5_400_000);
+  expect(parseDuration('2d 4h')).toBe(187_200_000);
+  expect(parseDuration('250ms')).toBe(250);
+  expect(parseDuration('  90s  ')).toBe(90_000);
+  expect(parseDuration('1m 30s')).toBe(90_000);
+  expect(parseDuration('0.0004s')).toBe(0);
+});
+
+test('parseDuration rejects invalid input with the quoted input in the message', () => {
+  for (const bad of ['', '   ', '10', '5x', 'h', '-1s', '1.s', '1h 5']) {
+    expect(() => parseDuration(bad)).toThrow(`${JSON.stringify(bad)}`);
+  }
+});
+
+test('formatDuration examples and round trip', () => {
+  expect(formatDuration(5_400_000)).toBe('1h30m');
+  expect(formatDuration(1_500)).toBe('1s500ms');
+  expect(formatDuration(90_061_001)).toBe('1d1h1m1s1ms');
+  expect(formatDuration(60_000)).toBe('1m');
+  expect(formatDuration(0)).toBe('0s');
+  expect(() => formatDuration(-1)).toThrow();
+  for (const x of [0, 1, 999, 60_000, 5_400_000, 90_061_001]) {
+    expect(parseDuration(formatDuration(x))).toBe(x);
+  }
+});
+
+test('formatDuration handles non-finite and fractional input', () => {
+  expect(() => formatDuration(NaN)).toThrow();
+  expect(() => formatDuration(Infinity)).toThrow();
+  expect(formatDuration(0.4)).toBe('0s');
+  expect(formatDuration(1.6)).toBe('2ms');
+});
+
+test('parseDuration treats any whitespace between parts as a separator, as the pattern does', () => {
+  expect(parseDuration('1h\t30m')).toBe(5_400_000);
+  expect(parseDuration('1h\n30m')).toBe(5_400_000);
+});
